head.script:
// 테스트 설명, 유효성 값 설정
//  - _2 : textImageRenderType='div' 일때 alt -> button title·aria-label, button 크기 조정과 CSS 선택자 단서 담당 (Cell 구조·클래스는 _1)
//  - 검증 대상 2개 Column 모두 textImageRenderType='div' 고정, 이미지 원본 크기가 서로 다름 (첨부 16 x 16 / 담당자 20 x 20)
scwin.tData = {
    "description" : "[column > P > textImageRenderType]<br/>inputType='textImage' 인 Column 에서 텍스트와 이미지를 표시하는 Cell 의 HTML 구조를 설정합니다.",
    "validation" : [
        "textImageRenderType='div' 일때 Column 의 alt 속성값은 'button' 요소의 title, aria-label 속성으로 적용됩니다.",
        "textImageRenderType='div' 인 경우 이미지의 크기에 맞게 button 요소의 크기가 조정됩니다.",
        "단, CSS 에 '.w2grid .gridBodyDefault button' 선택자가 정의되어 있다면 button 요소가 자동 조정되지 않을 수 있습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_alt.setValue("파일 열기");
    con_imageSize.setValue("");
    con_buttonSelector.setValue("Y");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 공통 CSS(base.css) 의 '.w2grid .gridBodyDefault button' 규칙 정의/미정의 전환 (validation 3 대조)
//  - 미정의 : 규칙의 선언을 비워 두고 원래 선언은 보관 / 정의 : 보관한 선언을 되돌림
scwin.setButtonSelector = function (isDefined) {
    for (let i = 0; i < document.styleSheets.length; i++) {
        let rules = null;
        try {
            rules = document.styleSheets[i].cssRules;
        } catch (e) {
            continue;
        }
        if (!rules) {
            continue;
        }
        for (let j = 0; j < rules.length; j++) {
            let rule = rules[j];
            if (rule.selectorText !== ".w2grid .gridBodyDefault button") {
                continue;
            }
            if (!isDefined && typeof rule.wqBackupCss === "undefined") {
                rule.wqBackupCss = rule.style.cssText;
                rule.style.cssText = "";
            } else if (isDefined && typeof rule.wqBackupCss !== "undefined") {
                rule.style.cssText = rule.wqBackupCss;
                delete rule.wqBackupCss;
            }
        }
    }
}



// comp 생성
//  - 검증 대상 : 첨부 Body Column(file, 이미지 ico_file.svg 16 x 16) / 담당자 Body Column(manager, 이미지 ico_grid_add.svg 20 x 20)
//    두 Column 모두 inputType='textImage', viewType='icon', textImageRenderType='div' 고정
//    alt / 이미지 크기(imageWidth, imageHeight) 는 옵션값을 두 Column 에 같이 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    let cAlt = con_alt.getValue();
    let cImageSize = con_imageSize.getValue();
    let cButtonSelector = con_buttonSelector.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 첨부, 담당자 Body Column 은 textImageRenderType=div 고정, 이미지 원본 크기 첨부 16 x 16 / 담당자 20 x 20\n[전제] .w2grid .gridBodyDefault button 선택자는 공통 CSS 에 정의되어 있으며 미정의 선택 시 이 페이지에서만 해제\n[확인] button 확인 버튼 -> 전체 Row button 의 배경 이미지 / 크기 / title / aria-label"', '', 'label1');

    scwin.setButtonSelector(cButtonSelector !== "N");

    let strNameSpace = $c.gcm.getNameSpace();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="docName" name="docName" dataType="text"></w2:column>';
    strDlt += '<w2:column id="file" name="file" dataType="text"></w2:column>';
    strDlt += '<w2:column id="manager" name="manager" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "docName" : "2026년 견적서", "file" : "견적서.pdf", "manager" : "김민수" },
        { "docName" : "공급 계약서", "file" : "계약서.docx", "manager" : "이영희" },
        { "docName" : "주간 회의록", "file" : "회의록.hwp", "manager" : "박지훈" }
    ], false);

    // 검증 대상 Body Column 공통 속성
    let attrCommon = ' inputType="textImage" viewType="icon" textImageRenderType="div"';
    if (cAlt !== '') {
        attrCommon += ' alt="' + cAlt + '"';
    }
    if (cImageSize !== '') {
        let size = cImageSize.split("x");
        attrCommon += ' imageWidth="' + size[0] + '" imageHeight="' + size[1] + '"';
    }

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:500px;height:180px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="column1" value="문서명"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="column2" value="첨부"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column3" value="담당자"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="docName" value=""></w2:column>';
    strTarget += '<w2:column width="170" style="" id="file" value="" imageSrc="/cm/images/base/ico_file.svg"' + attrCommon + '></w2:column>';
    strTarget += '<w2:column width="150" style="" id="manager" value="" imageSrc="/cm/images/base/ico_grid_add.svg"' + attrCommon + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 이미지 URL 의 원본 크기 (로드 완료 후 판정)
scwin.getNaturalSize = function (url) {
    return new Promise(function (resolve) {
        let img = new Image();
        img.onload = function () { resolve({ width : img.naturalWidth, height : img.naturalHeight }); };
        img.onerror = function () { resolve({ width : 0, height : 0 }); };
        img.src = url;
    });
}



// validation 1 ~ 3 판정 출력 : 전체 Row 첨부 / 담당자 Cell 의 button
//  - 배경 이미지 파일명과 원본 크기, 배경 이미지 표시 크기(background-size 기준), button 크기, title / aria-label
scwin.btn_checkButton_onclick = async function () {
    let rowCount = dlt_bind.getRowCount();
    let columns = [{ index : 1, name : "첨부" }, { index : 2, name : "담당자" }];
    let lines = [];
    for (let i = 0; i < rowCount; i++) {
        for (let c = 0; c < columns.length; c++) {
            let td = document.querySelector("[id='" + target1.id + "_cell_" + i + "_" + columns[c].index + "']");
            let btn = td ? td.querySelector("button") : null;
            if (!btn) {
                lines.push("Row " + i + " " + columns[c].name + " : button 없음");
                continue;
            }
            let cs = window.getComputedStyle(btn);
            let bgUrl = cs.backgroundImage.replace(/^url\(["']?/, "").replace(/["']?\)$/, "");
            let natural = await scwin.getNaturalSize(bgUrl);

            // 배경 이미지 표시 크기 : background-size 가 auto 면 원본 크기 (한쪽만 지정이면 원본 비율)
            let bgSize = cs.backgroundSize.split(" ");
            let imgW = bgSize[0] !== "auto" ? parseFloat(bgSize[0]) : null;
            let imgH = (bgSize.length > 1 && bgSize[1] !== "auto") ? parseFloat(bgSize[1]) : null;
            if (imgW === null && imgH === null) {
                imgW = natural.width;
                imgH = natural.height;
            } else if (imgW === null) {
                imgW = natural.height > 0 ? Math.round(imgH * natural.width / natural.height) : 0;
            } else if (imgH === null) {
                imgH = natural.width > 0 ? Math.round(imgW * natural.height / natural.width) : 0;
            }

            let rect = btn.getBoundingClientRect();
            let strTitle = btn.hasAttribute("title") ? "'" + btn.getAttribute("title") + "'" : "없음";
            let strAria = btn.hasAttribute("aria-label") ? "'" + btn.getAttribute("aria-label") + "'" : "없음";
            lines.push("Row " + i + " " + columns[c].name + " : 배경 이미지 " + bgUrl.split("/").pop() + " (원본 " + natural.width + " x " + natural.height + ", 표시 " + imgW + " x " + imgH + ")"
                + " / button " + Math.round(rect.width) + " x " + Math.round(rect.height)
                + " / title " + strTitle + " / aria-label " + strAria);
        }
    }
    wf_body_bottom.getObj("scwin").setReturnValue(lines.join("\n"));
}
